/* vt3rt: loader, indirect-call dispatch, and x87 helpers for recompiled code. */
#include "vt3rt.h"

#include "vt3/vt3_guest.h"
#include "vt3shim/shim.h"
#include "vt3shim/thunk.h"

#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <time.h>
#include <unistd.h>

/* Guest thread id for the trace. Defined in shim/src/kernel32_thread.c. */
uint32_t vt3s_current_tid(void);

/* The shim is the native runtime's (runtime/shim). Its adapter table is
 * generated by gen_adapters.py from the same headers. */

uint8_t *vt_mem = NULL;

#define VT_STACK_TOP 0x10000000u
#define VT_TEB 0x0FE00000u          /* inside the arena, below the stack */
#define VT_TOKEN_BASE 0xFFFF0000u   /* import tokens, never memory */
#define VT_SHIM_TOKEN_BASE 0xFFF00000u /* shim functions, for guest vtables (vt3shim_fn_token) */
#define VT_SENTINEL_RET 0xFFFFFFF0u /* return address for the entry call */

typedef struct {
    uint32_t addr;
    vt3_fnptr fn;
    const char *name;
} icent;

static icent *itab = NULL;
static size_t nitab = 0;
static int trace = 0;

/* ---- Skip intro (VT3_SKIP_INTRO) ----------------------------------------------------------
 * Game addresses are for the NoCD 1.0.1 VT3.exe (ImageBase 0x400000). See skipintro/plan.md.
 *   mode 1: the debug-menu entry "Tennis (Skip Intro)" runs instead of "Tennis". The game is built
 *           with Game::skipIntro = 1, so the logo scene hands over to the Title scene at once.
 *   mode 2: also press Start on pad 0 once the Title scene is up, which goes on to the front end. */
#define VA_GAME_PTR        0x009abe88u  /* Game* (size 0x2b4) */
#define VA_DBGMENU_FN_SLOT 0x00859684u  /* function pointer of the "Tennis" debug entry, jumped to by 0x44041d */
#define FN_TENNIS          0x00440910u  /* new Game(skipIntro=0), then the main loop */
#define FN_TENNIS_SKIP     0x00440930u  /* new Game(skipIntro=1), then the main loop */
#define VTBL_TITLE_SCENE   0x007649d8u  /* Title (press start) scene class */
#define FN_PAD_ASSIGN      0x004aec20u  /* thiscall PadMgr::Assign(int pad) */
#define OFF_GAME_STATEMGR  0xa8u
#define OFF_GAME_PADMGR    0x7cu
#define OFF_SM_CURSCENE    0x38u
#define OFF_SCENE_FRAME    0x10u

static int skip_mode = 0;
static int skip_pressed = 0;
static int skip_trace = 0;
static uint32_t skip_last_scene = 0;

/* Run a guest thiscall(ecx, arg) below the live frames of the calling (main) thread. */
static void guest_thiscall1(const vt3_cpu *cur, uint32_t fn, uint32_t ecx, uint32_t arg)
{
    vt3_cpu n;
    memset(&n, 0, sizeof n);
    n.esp = cur->esp - 256u;
    n.esp -= 4;
    wr32(n.esp, arg);
    n.esp -= 4;
    wr32(n.esp, VT_SENTINEL_RET);
    n.ecx = ecx;
    n.fs_base = cur->fs_base;
    n.fcw = 0x37Fu;
    vt_icall(&n, fn);
}

/* Called on the main thread from inside PeekMessageA, so once per rendered frame. */
static void skip_intro_hook(const vt3_cpu *cur)
{
    uint32_t game = rd32(VA_GAME_PTR);
    if (!game) return;
    uint32_t sm = rd32(game + OFF_GAME_STATEMGR);
    if (!sm) return;
    uint32_t scene = rd32(sm + OFF_SM_CURSCENE);
    if (skip_trace && scene != skip_last_scene) {
        skip_last_scene = scene;
        uint32_t pad = rd32(game + OFF_GAME_PADMGR);
        fprintf(stderr, "vt3: scene -> %08x vtbl %08x (init %08x update %08x) mode %u padAssigned %u\n",
                scene, scene ? rd32(scene) : 0, scene ? rd32(rd32(scene) + 4) : 0,
                scene ? rd32(rd32(scene) + 8) : 0, rd32(sm + 0x34), pad ? rd8(pad + 8) : 0);
    }
    if (skip_mode != 2 || skip_pressed) return;
    if (!scene || rd32(scene) != VTBL_TITLE_SCENE) return;
    if (rd32(scene + OFF_SCENE_FRAME) < 12) return;          /* let the title fade in first */
    uint32_t pad = rd32(game + OFF_GAME_PADMGR);
    if (!pad) return;
    skip_pressed = 1;
    fprintf(stderr, "vt3: skip intro: pressing Start on pad 0 (title scene %08x)\n", scene);
    guest_thiscall1(cur, FN_PAD_ASSIGN, pad, 0);
}

/* One MSG (hwnd, message, wParam, lParam at offsets 0, 4, 8, 12) from guest memory. */
static void vt_trace_msg(const char *what, uint32_t p)
{
    if (!p || p >= (1u << 30)) return;
    fprintf(stderr, "vt3: msg %s hwnd=%08x message=%08x wparam=%08x lparam=%08x [t%u]\n", what,
            rd32(p), rd32(p + 4), rd32(p + 8), rd32(p + 12), vt3s_current_tid());
}

uint64_t vt_rdtsc(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}

void vt_die_at(uint32_t addr, uint32_t detail)
{
    fflush(stdout);
    fprintf(stderr, "vt3: fault at guest %08x (detail %08x)\n", addr, detail);
    exit(99);
}

void vt_unsupported_at(uint32_t addr, const char *text)
{
    fflush(stdout);
    fprintf(stderr, "vt3: unsupported instruction at %08x: %s\n", addr, text);
    exit(98);
}

static int icent_cmp(const void *a, const void *b)
{
    const icent *x = a, *y = b;
    return (x->addr > y->addr) - (x->addr < y->addr);
}

void vt_icall(vt3_cpu *c, uint32_t target)
{
    /* Every call the game makes into a host import comes through here - D3D9 methods, the Win32
     * calls, thousands a frame - and the entry was found by binary searching 572 sorted addresses,
     * about nine compares each. The same handful of targets accounts for almost all of it, so a
     * direct-mapped cache of the last target each slot saw turns the common case into one load and
     * one compare. Profiled at 9.6% of CPU on the Retroid before this. The store below is a plain
     * one on purpose: a racing guest thread can only ever install a valid entry, and the address
     * check makes a torn or stale slot a miss rather than a wrong call. */
    enum { ICACHE = 1024 };
    static icent *icache[ICACHE];
    uint32_t slot = (target >> 2) & (ICACHE - 1u);
    icent *e = icache[slot];
    if (!e || e->addr != target) {
        size_t lo = 0, hi = nitab;
        while (lo < hi) {
            size_t mid = lo + (hi - lo) / 2;
            if (itab[mid].addr < target) lo = mid + 1;
            else hi = mid;
        }
        if (lo >= nitab || itab[lo].addr != target) {
            fflush(stdout);
            fprintf(stderr, "vt3: indirect transfer to unknown guest address %08x\n", target);
            exit(97);
        }
        e = &itab[lo];
        icache[slot] = e;
    }
    if (((skip_mode == 2 && !skip_pressed) || skip_trace) && e->name && !strcmp(e->name, "PeekMessageA") &&
        vt3s_current_tid() == 1)
        skip_intro_hook(c);
    if (!e->fn) {
        fflush(stdout);
        fprintf(stderr, "vt3: unimplemented import %s\n", e->name);
        exit(96);
    }
    if (trace) {
        /* Show the first argument as a string for the calls that take names. */
        const char *arg = "";
        if (!strcmp(e->name, "LoadLibraryA") || !strcmp(e->name, "GetModuleHandleA") ||
            !strcmp(e->name, "GetProcAddress") || !strcmp(e->name, "CreateFileA")) {
            uint32_t p = rd32(c->esp + 4);
            if (p && p < (1u << 30)) arg = (const char *)(vt_mem + p);
        }
        fprintf(stderr, "vt3: call %s %s from %08x [t%u]", e->name, arg, rd32(c->esp),
                vt3s_current_tid());
        /* Walk the EBP chain: the CRT and most game code keep frame pointers. */
        uint32_t bp = c->ebp;
        for (int depth = 0; depth < 6 && bp && bp < (1u << 30); depth++) {
            fprintf(stderr, " <- %08x", rd32(bp + 4));
            bp = rd32(bp);
        }
        fprintf(stderr, "\n");
    }
    /* Message traffic, for comparing with a Wine trace. Get/PeekMessage fill the MSG on a
     * return; DispatchMessage reads the MSG it is given. */
    uint32_t msg_arg = 0;
    int msg_kind = 0;   /* 1 = Get/PeekMessage, 2 = DispatchMessage */
    if (trace) {
        if (!strcmp(e->name, "GetMessageA") || !strcmp(e->name, "PeekMessageA")) msg_kind = 1;
        else if (!strcmp(e->name, "DispatchMessageA")) msg_kind = 2;
        if (msg_kind) msg_arg = rd32(c->esp + 4);
        if (msg_kind == 2) vt_trace_msg("dispatch", msg_arg);
    }
    /* A shim may call guest code (window procedures). Record this frame's stack pointer so the
     * nested call starts below it. */
    uint32_t sp_slot = c->fs_base + VT3SHIM_TEB_GUEST_SP, saved_sp;
    memcpy(&saved_sp, vt_mem + sp_slot, 4);
    memcpy(vt_mem + sp_slot, &c->esp, 4);
    e->fn(c);
    memcpy(vt_mem + sp_slot, &saved_sp, 4);
    if (msg_kind == 1 && c->eax) vt_trace_msg("returned", msg_arg);
}

/* ---- x87 ----------------------------------------------------------------- *
 *
 * The one-memory-access helpers (vt_ldf32/vt_stf64/...) are static inline in vt3rt.h; see the
 * comment there. What is left here is the one that needs a rounding mode. */

uint32_t vt_cvt_i32(double v, int tr)
{
    double r = tr ? trunc(v) : nearbyint(v);
    if (!(r >= -2147483648.0 && r < 2147483648.0)) return 0x80000000u;
    return (uint32_t)(int32_t)r;
}

vt_xmm vt_ldx(uint32_t a)
{
    vt_xmm v;
    memcpy(v.b, vt_mem + a, 16);
    return v;
}

void vt_stx(uint32_t a, vt_xmm v)
{
    memcpy(vt_mem + a, v.b, 16);
}

/* ---- loader -------------------------------------------------------------- */

/* Import name ("DLL!Name" or "Name") to shim adapter. NULL when the shim has none. */
static vt3_fnptr shim_lookup(const char *name)
{
    const char *bare = name;
    for (const char *p = name; *p; p++)
        if (*p == '!') bare = p + 1;
    for (size_t i = 0; i < vt3_shim_count; i++)
        if (strcmp(vt3_shim_table[i].name, bare) == 0) return vt3_shim_table[i].fn;
    return NULL;
}

/* Guest address for shim function `name` (runtime/shim/include/vt3shim/thunk.h). */
uint32_t vt3shim_fn_token(const char *name)
{
    for (size_t i = 0; i < vt3_shim_count; i++)
        if (strcmp(vt3_shim_table[i].name, name) == 0) return VT_SHIM_TOKEN_BASE + 16u * (uint32_t)i;
    return 0;
}

/* Ordinal-only imports have no name in the import table. The shim binds by name, so map the
 * ordinals it needs. DSOUND ordinal 11 is DirectSoundCreate. */
static const char *shim_import_name(const vt3_import *im)
{
    if (strncmp(im->name, "ORD", 3) == 0 && im->dll && strcasecmp(im->dll, "DSOUND.dll") == 0 &&
        strtol(im->name + 3, NULL, 10) == 11)
        return "DirectSoundCreate";
    return im->name;
}

static void put32(uint32_t a, uint32_t v)
{
    memcpy(vt_mem + a, &v, 4);
}

/* Runs a guest function on the given stack, stdcall style, for the shim's threads and timers.
 * The arguments are pushed right to left, and a sentinel return address goes under them. The
 * callee pops its own arguments. */
static uint32_t guest_call_hook(uint32_t stack_top, uint32_t teb, uint32_t fn,
                                const uint32_t *args, uint32_t nargs)
{
    vt3_cpu c;
    memset(&c, 0, sizeof c);
    c.esp = stack_top;
    for (uint32_t i = nargs; i-- > 0;) {
        c.esp -= 4;
        put32(c.esp, args[i]);
    }
    c.esp -= 4;
    put32(c.esp, VT_SENTINEL_RET);
    c.fs_base = teb;
    c.fcw = 0x37Fu;
    vt_icall(&c, fn);
    return c.eax;
}

/* ---- Serve trace (VT3_TRACE_SERVE) -------------------------------------------------------
 * Three points in the serve-angle function at 0x4825c0 (see recomp.py TRACE_POINTS):
 *   0x4825c0  entry: the input vector (its pointer is the first argument), the flag, and the
 *             reference point at this+0xa0 (x) and this+0xa8 (z). dx = x - rx, dz = z - rz.
 *   0x482624  the atan2 result, stored at [esp+4] before the call to 0x4e5b80.
 *   0x482629  after the call: eax points at the direction vector, which the game reads from
 *             xmm0..xmm2.
 */
int vt_trace_serve = 0;

static float vt_rdf(uint32_t a)
{
    float f;
    memcpy(&f, vt_mem + a, 4);
    return f;
}

void vt_serve_point(vt3_cpu *c, uint32_t addr)
{
    if (addr == 0x4825c0u) {
        uint32_t in = rd32(c->esp + 4);
        float x = vt_rdf(in), y = vt_rdf(in + 4), z = vt_rdf(in + 8);
        float rx = vt_rdf(c->ecx + 0xa0u), rz = vt_rdf(c->ecx + 0xa8u);
        fprintf(stderr, "vt3 serve: in=(%g, %g, %g) flag=%u ref=(%g, %g) dx=%g dz=%g\n",
                x, y, z, rd8(c->esp + 0xcu), rx, rz, x - rx, z - rz);
    } else if (addr == 0x482624u) {
        float ang = vt_rdf(c->esp + 4u);
        fprintf(stderr, "vt3 serve: atan2 = %g rad (%g deg)\n", ang, ang * 57.2957795f);
    } else if (addr == 0x482629u) {
        uint32_t v = c->eax;
        fprintf(stderr, "vt3 serve: dir = (%g, %g, %g) at %08x\n",
                vt_rdf(v), vt_rdf(v + 4), vt_rdf(v + 8), v);
    }
}

int vt3_run(const vt3_module *m, const char *image_path)
{
    trace = getenv("VT3_TRACE") != NULL;
    vt_trace_serve = getenv("VT3_TRACE_SERVE") != NULL;

    /* One guest arena from the native runtime. Guest address A is vt_mem + A,
     * so vt_mem is the host address of guest 0. vt3_g2h(0) is NULL by design,
     * so the base comes from the image address and is subtracted back out. */
    if (vt3_guest_init(VT3_GUEST_DEFAULT_BYTES) != 0) return 1;
    uint8_t *img_host = vt3_g2h(VT3_GUEST_IMAGE_BASE);
    if (!img_host) {
        fprintf(stderr, "vt3: guest arena too small for the image\n");
        return 1;
    }
    vt_mem = img_host - VT3_GUEST_IMAGE_BASE;

    FILE *f = fopen(image_path, "rb");
    if (!f) {
        fprintf(stderr, "vt3: cannot open %s\n", image_path);
        return 1;
    }
    size_t got = fread(vt_mem + m->image_base, 1, m->image_size, f);
    fclose(f);
    if (got != m->image_size) {
        fprintf(stderr, "vt3: %s is %zu bytes, expected %u\n", image_path, got, m->image_size);
        return 1;
    }

    {
        const char *sk = getenv("VT3_SKIP_INTRO");
        skip_mode = sk ? atoi(sk) : 2;   /* default: straight to the front end. VT3_SKIP_INTRO=0 turns it off. */
        skip_trace = getenv("VT3_SKIP_TRACE") != NULL;
        if (skip_mode >= 1) {
            if (rd32(VA_DBGMENU_FN_SLOT) == FN_TENNIS) {
                wr32(VA_DBGMENU_FN_SLOT, FN_TENNIS_SKIP);
                fprintf(stderr, "vt3: skip intro: debug entry %08x -> %08x (mode %d)\n",
                        FN_TENNIS, FN_TENNIS_SKIP, skip_mode);
            } else {
                fprintf(stderr, "vt3: skip intro: slot %08x holds %08x, not patching\n",
                        VA_DBGMENU_FN_SLOT, rd32(VA_DBGMENU_FN_SLOT));
                skip_mode = 0;
            }
        }
    }

    /* TEB: the few fields the CRT and SEH read through FS. */
    put32(VT_TEB + 0x00, 0xFFFFFFFFu);          /* SEH chain end */
    put32(VT_TEB + 0x04, VT_STACK_TOP);         /* stack base */
    put32(VT_TEB + 0x08, VT_STACK_TOP - (1u << 20)); /* stack limit */
    put32(VT_TEB + 0x18, VT_TEB);               /* self */
    put32(VT_TEB + 0x30, VT_TEB + 0x1000);      /* PEB */

    vt3shim_set_game_root(getenv("VT3_GAME_ROOT") ? getenv("VT3_GAME_ROOT") : ".");
    if (vt3shim_init() != 0) return 1;
    vt3shim_set_guest_call(guest_call_hook);
    vt3shim_thread_begin_main();
    vt3shim_set_main_teb(VT_STACK_TOP, VT_TEB);

    /* Imports: each IAT slot gets a unique token. Calls through the slot land in
     * the icall table, which maps the token to a shim. */
    size_t nimp = m->nimps;
    icent *tab = calloc(m->nfns + nimp + vt3_shim_count, sizeof *tab);
    if (!tab) return 1;
    size_t n = 0;
    for (size_t i = 0; i < m->nfns; i++) {
        tab[n].addr = m->fns[i].addr;
        tab[n].fn = m->fns[i].fn;
        tab[n].name = m->fns[i].name;
        n++;
    }
    for (size_t i = 0; i < nimp; i++) {
        const vt3_import *im = &m->imps[i];
        uint32_t tok = VT_TOKEN_BASE + 16u * (uint32_t)i;
        put32(im->slot, tok);
        tab[n].addr = tok;
        tab[n].fn = shim_lookup(shim_import_name(im));
        tab[n].name = im->name;
        n++;
    }
    for (size_t i = 0; i < vt3_shim_count; i++) {
        tab[n].addr = VT_SHIM_TOKEN_BASE + 16u * (uint32_t)i;
        tab[n].fn = vt3_shim_table[i].fn;
        tab[n].name = vt3_shim_table[i].name;
        n++;
    }
    qsort(tab, n, sizeof *tab, icent_cmp);
    itab = tab;
    nitab = n;

    vt3_cpu c = {0};
    c.esp = VT_STACK_TOP - 64;
    c.esp -= 4;
    put32(c.esp, VT_SENTINEL_RET);
    c.fs_base = VT_TEB;
    c.fcw = 0x37Fu;

    vt_icall(&c, m->entry);
    /* The entry is expected to call ExitProcess. Returning means it did not. */
    fflush(stdout);
    vt3shim_shutdown();
    vt3_guest_shutdown();
    return 0;
}
